"use strict";(self.webpackChunkicecat_connector_doc=self.webpackChunkicecat_connector_doc||[]).push([[649],{6534(t,e,o){o.r(e),o.d(e,{comp:()=>a,data:()=>i});var r=o(641);const n={},a=(0,o(6262).A)(n,[["render",function(t,e){return(0,r.uX)(),(0,r.CE)("div",null,[...e[0]||(e[0]=[(0,r.Fv)('<h1 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>Features</span></a></h1><p>Every feature below is available from <strong>Webkul WC Addons → IceCat Connector</strong> in your WordPress admin.</p><hr><h2 id="importing" tabindex="-1"><a class="header-anchor" href="#importing"><span>Importing</span></a></h2><ul><li><strong>Import products from the Icecat catalog</strong> using any of three search methods: <strong>Icecat ID</strong>, <strong>GTIN</strong> (EAN/UPC barcode), or <strong>Product Code &amp; Brand</strong>.</li><li><strong>Choose the catalog language</strong> per import — around 80 languages are available, from English and French to Japanese and Arabic.</li><li><strong>Review before you import</strong>: the connector shows the fetched title, IDs, brand, product code, and short description first; you create the product only when it looks right.</li><li><strong>Duplicate protection</strong>: if a catalog product is already in your store, the connector tells you, links to the existing product, and offers a one-click <strong>Update Existing Product</strong> instead of creating a copy.</li><li><strong>Bulk import via CSV</strong> — upload a file of Icecat IDs, GTINs, or product codes and import everything in one background run, with live progress and a downloadable failed-items report. Sample CSVs are provided for every format.</li></ul><h2 id="product-content" tabindex="-1"><a class="header-anchor" href="#product-content"><span>Product Content</span></a></h2><ul><li><strong>Full product build</strong>: title, short description, long description (including the technical specification content), SKU from the manufacturer&#39;s product code, GTIN, and release dates.</li><li><strong>Image galleries</strong>: the featured image and all gallery images are downloaded from Icecat into your Media Library.</li><li><strong>Technical specifications as attributes</strong>: Icecat&#39;s spec sheet becomes WooCommerce product attributes, shown on the product page&#39;s <em>Additional information</em> tab.</li><li><strong>Image quality control</strong>: import High, Medium, or Low resolution images.</li></ul><h2 id="categories" tabindex="-1"><a class="header-anchor" href="#categories"><span>Categories</span></a></h2><ul><li><strong>Import with the Icecat category</strong> — the product&#39;s own catalog category is created in WooCommerce and assigned automatically, or</li><li><strong>Map to your WooCommerce categories</strong> — pick one or more existing store categories for the import (products with no selection go to <em>Uncategorized</em>).</li></ul><h2 id="store-controls" tabindex="-1"><a class="header-anchor" href="#store-controls"><span>Store Controls</span></a></h2><ul><li><strong>Product status on creation</strong>: Draft, Publish, or Pending Review — your choice applies to every import.</li><li><strong>Default stock quantity</strong>: new products get this quantity with stock management enabled (set 0 to leave stock management off).</li><li><strong>Background processing</strong>: create images and attributes in the background so imports finish fast, or switch to inline processing to have everything ready the moment the product is created.</li></ul><h2 id="keeping-products-current" tabindex="-1"><a class="header-anchor" href="#keeping-products-current"><span>Keeping Products Current</span></a></h2><ul><li><strong>Update Details From IceCat</strong> — one button on the product edit page re-fetches the latest catalog data for that product.</li><li><strong>Replace Details From IceCat</strong> — link any existing simple product to an Icecat ID and replace its content with catalog data.</li><li><strong>Bulk Update</strong> — select products in the connector list and update them all from Icecat.</li><li><strong>Refresh All Products</strong> — re-import the latest data for every connected product in the background, with a live progress card and completion notice.</li></ul><h2 id="product-management" tabindex="-1"><a class="header-anchor" href="#product-management"><span>Product Management</span></a></h2><ul><li><strong>Dedicated product list</strong> with product ID, image, name, Icecat ID, GTIN, brand &amp; code, import date, and status.</li><li><strong>Search by Icecat ID</strong> to find any import instantly.</li><li><strong>Bulk actions</strong>: Delete (with confirmation), Update, Trash, and Product Publish.</li><li><strong>Direct Icecat link</strong> per product — open the product&#39;s page on icecat.biz in one click.</li></ul><h2 id="onboarding-compatibility" tabindex="-1"><a class="header-anchor" href="#onboarding-compatibility"><span>Onboarding &amp; Compatibility</span></a></h2><ul><li><strong>Guided Setup Wizard</strong> with live connection verification — including a check that a supplied Full Icecat App Key really unlocks Full Icecat content.</li><li><strong>HPOS and cart/checkout blocks compatible</strong>; works with WooCommerce 10.0–11.0 and WordPress 6.7–7.0.</li></ul>',17)])])}]]),i=JSON.parse('{"path":"/icecat-connector/features.html","title":"Features","lang":"en-US","frontmatter":{"title":"Features","description":"Everything the WooCommerce IceCat Connector can do — search methods, bulk CSV import, category mapping, background processing, product updates, and more."},"headers":[{"level":2,"title":"Importing","slug":"importing","link":"#importing","children":[]},{"level":2,"title":"Product Content","slug":"product-content","link":"#product-content","children":[]},{"level":2,"title":"Categories","slug":"categories","link":"#categories","children":[]},{"level":2,"title":"Store Controls","slug":"store-controls","link":"#store-controls","children":[]},{"level":2,"title":"Keeping Products Current","slug":"keeping-products-current","link":"#keeping-products-current","children":[]},{"level":2,"title":"Product Management","slug":"product-management","link":"#product-management","children":[]},{"level":2,"title":"Onboarding & Compatibility","slug":"onboarding-compatibility","link":"#onboarding-compatibility","children":[]}],"git":{},"filePathRelative":"icecat-connector/features.md"}')}}]);